insert into public.hospitals (name, city, state, country, operational_status, medisync_tier, tier_basis, catalog_metadata) select 'Global Hospitals', 'Chennai', 'Tamil Nadu', 'India', 'ACTIVE', 'Tier 2', 'By Hospital Type', jsonb_build_object('ownership','Private (Corporate)','district','Chennai','notes','Multi-specialty, transplant care','source','Tamil_Nadu_Hospitals_3_Tier.xlsx') where not exists (select 1 from public.hospitals h where lower(h.name)=lower('Global Hospitals') and lower(coalesce(h.city,''))=lower('Chennai'));
